test('an unexpected error is a generic JSON 500 with no internals', async () => {
  const failing = createApp({
    repo: {
      list: async () => {
        throw new Error('secret connection string postgres://db')
      },
    },
  })
  const srv = failing.listen(0)
  await new Promise((resolve) => srv.once('listening', resolve))
  const originalError = console.error
  console.error = () => {}
  try {
    const res = await fetch(`http://127.0.0.1:${srv.address().port}/api/orders`)
    const body = await res.text()
    assert.equal(res.status, 500)
    assert.doesNotMatch(body, /secret|at .*\.mjs/)
    assertError({ status: res.status, body: JSON.parse(body), type: res.headers.get('content-type') }, 500, 'internal_error')
  } finally {
    console.error = originalError
    await new Promise((resolve) => srv.close(resolve))
  }
})
